<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Pterodactyl\Models\Dezerx\DiscordBot; class Style { private static ?Style $current = null; private static ?array $allowed = null; private static ?array $powerActions = null; public function __construct(public readonly array $design) { } public static function for(?DiscordBot $bot): self { return new self(BotSettings::design($bot)); } public static function use(self $style, ?array $allowed = null, ?array $powerActions = null): void { self::$current = $style; self::$allowed = $allowed; self::$powerActions = $powerActions; } public static function powerAction(string $action): bool { return self::$powerActions === null || in_array($action, self::$powerActions, true); } public static function current(): self { return self::$current ??= new self(BotSettings::DESIGN); } public static function can(string $command): bool { return self::$allowed === null || in_array($command, self::$allowed, true); } public function accent(): int { $accent = (string) ($this->design['accent'] ?? ''); return $accent !== '' ? (int) hexdec(ltrim($accent, '#')) : BotConfig::accent(); } public function banner(?string $url): ?string { return ($this->design['banner'] ?? true) ? $url : null; } public function logo(?string $url): ?string { return ($this->design['logos'] ?? true) ? $url : null; } public function footer(): string { $footer = trim((string) ($this->design['footer'] ?? '')); return Format::escape($footer !== '' ? $footer : BotConfig::panelName()); } public function consoleLines(): int { return (int) ($this->design['console_lines'] ?? BotSettings::DESIGN['console_lines']); } public function consoleImage(): bool { return (bool) ($this->design['console_image'] ?? false) && BotConfig::consoleImagesAllowed(); } public function consoleFont(): int { return (int) ($this->design['console_font'] ?? BotSettings::DESIGN['console_font']); } public function barLength(): int { return (int) ($this->design['bar_length'] ?? BotSettings::DESIGN['bar_length']); } public function bar(?float $percent, ?int $width = null): string { $width ??= $this->barLength(); $style = (string) ($this->design['bars'] ?? 'squares'); if ($percent === null) { return $style === 'blocks' ? '`' . str_repeat('░', $width) . '`' : str_repeat('▫️', min($width, 5)); } $percent = max(0.0, min(100.0, $percent)); $filled = (int) round($percent / 100 * $width); $filled = $percent > 0 && $filled === 0 ? 1 : $filled; $level = $percent >= 90 ? 2 : ($percent >= 70 ? 1 : 0); return match ($style) { 'circles' => str_repeat(['🟢', '🟡', '🔴'][$level], $filled) . str_repeat('⚫', $width - $filled), 'blocks' => '`' . str_repeat('█', $filled) . str_repeat('░', $width - $filled) . '`', default => str_repeat(['🟩', '🟨', '🟥'][$level], $filled) . str_repeat('⬛', $width - $filled), }; } } 